<?php require_once 'db.php';require_once 'auth.php';bejelentkezesSzukseges();$oldalCim='Bevetések';function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$q=trim($_GET['q']??'');$where=[];$p=[];$oldal=max(1,(int)($_GET['oldal']??1));$meret=15;if($q!==''){ $where[]='(r.riasztas_szam LIKE ? OR r.helyszin LIKE ? OR r.telepules LIKE ? OR r.esemeny_tipus LIKE ? OR b.megjegyzes LIKE ? OR j.azonosito LIKE ? OR j.rendszam LIKE ? OR t.teljes_nev LIKE ? OR t.becenev LIKE ? OR bt.szerep LIKE ?)';for($i=0;$i<10;$i++)$p[]="%$q%";}$w=$where?'WHERE '.implode(' AND ',$where):'';$st=$pdo->prepare("SELECT COUNT(DISTINCT b.id) FROM bevetesek b LEFT JOIN riasztasok r ON r.id=b.riasztas_id LEFT JOIN jarmuvek j ON j.id=b.jarmu_id LEFT JOIN bevetes_tagok bt ON bt.bevetes_id=b.id LEFT JOIN tagok t ON t.id=bt.tag_id $w");$st->execute($p);$cnt=(int)$st->fetchColumn();$pages=max(1,(int)ceil($cnt/$meret));$oldal=min($oldal,$pages);$off=($oldal-1)*$meret;$st=$pdo->prepare("SELECT b.id,b.riasztas_id,b.indulas_ido,b.erkezes_ido,b.visszaindulas_ido,b.visszaerkezes_ido,b.megjegyzes,r.riasztas_szam,r.datum,r.helyszin,r.telepules,r.esemeny_tipus,r.allapot,j.azonosito,j.rendszam,j.marka,j.tipus,COUNT(DISTINCT bt.id) tag_db FROM bevetesek b LEFT JOIN riasztasok r ON r.id=b.riasztas_id LEFT JOIN jarmuvek j ON j.id=b.jarmu_id LEFT JOIN bevetes_tagok bt ON bt.bevetes_id=b.id LEFT JOIN tagok t ON t.id=bt.tag_id $w GROUP BY b.id ORDER BY r.datum DESC,r.riasztasi_ido DESC,b.id DESC LIMIT $meret OFFSET $off");$st->execute($p);$rows=$st->fetchAll();require 'header.php';?><div class="page-title"><div><span class="eyebrow">KIVONULÁSOK</span><h1>Bevetések</h1><p class="muted">A rögzített bevetések és kivonulások.</p></div><a href="bevetes_uj.php" class="btn btn-primary">+ Új bevetés</a></div><div class="card filters"><form method="get" class="filter-row"><input name="q" value="<?=e($q)?>" placeholder="Keresés riasztás, helyszín, jármű, tag..."><button class="btn btn-secondary">Keresés</button><a class="btn btn-light" href="bevetesek.php">Alaphelyzet</a></form></div><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Riasztás</th><th>Dátum / helyszín</th><th>Esemény</th><th>Jármű</th><th>Idők</th><th>Tagok</th><th>Műveletek</th></tr></thead><tbody><?php foreach($rows as $b):?><tr><td><strong><?=e($b['riasztas_szam'])?></strong><br><span class="muted">#<?=$b['id']?></span></td><td><?=e($b['datum'])?><br><?=e($b['helyszin'])?></td><td><?=e($b['esemeny_tipus'])?></td><td><?=e($b['azonosito']?:'—')?></td><td><?=e(substr((string)$b['indulas_ido'],0,5))?> → <?=e(substr((string)$b['erkezes_ido'],0,5))?><br><?=e(substr((string)$b['visszaindulas_ido'],0,5))?> → <?=e(substr((string)$b['visszaerkezes_ido'],0,5))?></td><td><?= (int)$b['tag_db'] ?></td><td><div class="table-actions"><a href="bevetes_reszletek.php?id=<?=$b['id']?>" class="btn btn-small btn-primary">Részletek</a><a href="bevetes_szerkeszt.php?id=<?=$b['id']?>" class="btn btn-small btn-secondary">Szerkesztés</a><?php if(jogosultsag('admin')):?><a href="bevetes_torles.php?id=<?=$b['id']?>" class="btn btn-small btn-danger">Törlés</a><?php endif;?></div></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty-state">Nincs találat.</td></tr><?php endif;?></tbody></table></div></div><?php if($pages>1):?><div class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$oldal?'active':''?>" href="?<?=http_build_query(['q'=>$q,'oldal'=>$i])?>"><?=$i?></a><?php endfor;?></div><?php endif;?><?php require 'footer.php';?>